def diff_baris(a, b):
    x, y = a.splitlines(), b.splitlines()
    n, m = len(x), len(y)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if x[i] == y[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
    hasil = []
    i = j = 0
    while i < n and j < m:
        if x[i] == y[j]:
            hasil.append((' ', x[i]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            hasil.append(('-', x[i]))
            i += 1
        else:
            hasil.append(('+', y[j]))
            j += 1
    hasil += [('-', t) for t in x[i:]]
    hasil += [('+', t) for t in y[j:]]
    return hasil

