import hashlib

def rantai_valid(commits):
    sebelumnya = None
    for c in commits:
        if c['parent'] != sebelumnya:
            return False
        isi = 'tree ' + c['tree'] + '\nparent ' + (c['parent'] or '') + '\n\n' + c['pesan']
        if hashlib.sha1(isi.encode('utf-8')).hexdigest() != c['id']:
            return False
        sebelumnya = c['id']
    return True

